"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminHorarios() {
    const days = ["Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo"];
    const hours = ["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00", "19:00", "20:00"];

    // State for blocked slots (simulated)
    const [blockedSlots, setBlockedSlots] = useState<string[]>(["Sábado-19:00", "Sábado-20:00", "Domingo-08:00", "Domingo-09:00"]);

    const toggleSlot = (day: string, hour: string) => {
        const slot = `${day}-${hour}`;
        setBlockedSlots(prev =>
            prev.includes(slot) ? prev.filter(s => s !== slot) : [...prev, slot]
        );
    };

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <header className="mb-10 lg:mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <h1 className="text-3xl font-semibold mb-1">
                        Horários <span className="text-[#D4AF37]">Disponíveis</span>
                    </h1>
                    <p className="text-gray-400 text-sm">Gerencie a grade de funcionamento e bloqueie horários específicos</p>
                </div>
                <div className="flex gap-4">
                    <Button variant="outline" className="gap-2">
                        <Icon name="Calendar" className="w-4 h-4" /> Ver Tudo
                    </Button>
                    <Button className="gap-2 bg-red-500/10 text-red-500 border-red-500/20 hover:bg-red-500 hover:text-white">
                        <Icon name="Lock" className="w-4 h-4" /> Bloquear Dia
                    </Button>
                </div>
            </header>

            <div className="bg-[#111111] border border-[#1f1f1f] rounded-3xl overflow-hidden shadow-2xl">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full border-collapse">
                        <thead>
                            <tr className="bg-[#161616] border-b border-[#1f1f1f]">
                                <th className="p-6 text-left text-[10px] uppercase tracking-widest text-gray-500 font-bold border-r border-[#1f1f1f] w-32">Horário</th>
                                {days.map(day => (
                                    <th key={day} className="p-6 text-center text-[10px] uppercase tracking-widest text-[#D4AF37] font-bold border-r border-[#1f1f1f] last:border-0 min-w-[120px]">
                                        {day}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-[#1f1f1f]">
                            {hours.map(hour => (
                                <tr key={hour} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-4 text-center border-r border-[#1f1f1f] font-bold text-gray-400 text-xs">
                                        {hour}
                                    </td>
                                    {days.map(day => {
                                        const isBlocked = blockedSlots.includes(`${day}-${hour}`);
                                        return (
                                            <td key={day} className="p-2 border-r border-[#1f1f1f] last:border-0 group">
                                                <button
                                                    onClick={() => toggleSlot(day, hour)}
                                                    className={`w-full py-4 rounded-xl text-[10px] font-bold uppercase transition-all flex items-center justify-center gap-2 ${isBlocked
                                                            ? 'bg-red-500/5 text-red-500/40 border border-transparent hover:border-red-500/20'
                                                            : 'bg-emerald-500/5 text-emerald-500 border border-transparent hover:bg-emerald-500/10 hover:border-emerald-500/30'
                                                        }`}
                                                >
                                                    {isBlocked ? (
                                                        <><Icon name="XCircle" className="w-3 h-3" /> Bloqueado</>
                                                    ) : (
                                                        <><Icon name="CheckCircle" className="w-3 h-3" /> Livre</>
                                                    )}
                                                </button>
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <div className="mt-10 flex gap-6 text-[10px] font-bold uppercase tracking-widest text-gray-500 bg-[#111111] p-6 rounded-2xl border border-[#1f1f1f] inline-flex">
                <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-emerald-500/20 border border-emerald-500/40" />
                    <span>Horário Disponível</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500/40" />
                    <span>Horário Bloqueado</span>
                </div>
            </div>
        </div>
    );
}
